export interface CatTrack extends Track {
  cats: string[]
}

function build(r: Raw): CatTrack {
  const [id, title, artist, duration, cats] = r
  return {
    id,
    source: 'youtube',
    title,
    artist,
    artistHandle: '',
    artwork: `https://i.ytimg.com/vi/${id}/hqdefault.jpg`,
    artworkLarge: `https://i.ytimg.com/vi/${id}/maxresdefault.jpg`,
    duration,
    playCount: 0,
    streamUrl: '',
    cats: cats ? cats.split('|') : [],
  }
}

export const PODCAST_TRACKS: CatTrack[] = RAW.map(build)

/** Episodes tagged with a given show label (e.g. "The Ranveer Show"). */
export function podcastsByCategory(label: string): CatTrack[] {
  return PODCAST_TRACKS.filter((t) => t.cats.includes(label))
}
